function shardFor(customerId: string, shardCount: number): number {
  if (shardCount < 1) throw new Error("shardCount must be positive");
  let hash = 0;
  for (const char of customerId) {
    hash = (hash * 31 + char.charCodeAt(0)) | 0;
  }
  return (hash >>> 0) % shardCount;
}

const shard = shardFor("customer-42", 8);
console.log(`Route to shard ${shard}`);

