from dataclasses import dataclass

@dataclass
class OrderSaga:
    order_id: str
    state: str = "NEW"

    def reserve_inventory(self):
        self.state = "INVENTORY_RESERVED"

    def compensate_inventory(self):
        self.state = "CANCELLED"

    def charge_payment(self, succeeds: bool):
        if not succeeds:
            self.compensate_inventory()
            return
        self.state = "PAID"

saga = OrderSaga("o-123")
saga.reserve_inventory()
saga.charge_payment(succeeds=False)
print(saga.state)  # CANCELLED

